import * as SciChart from "scichart";

// Data: the MNI ICBM 152 nonlinear symmetric 2009a template, T1-weighted and T2-weighted. It is an average of
// brain MRI scans of 152 adults, registered to each other, so it shows no individual person. Downloaded from
// https://www.bic.mni.mcgill.ca/ServicesAtlases/ICBM152NLin2009 and used under its licence:
//   Copyright (C) 1993-2004 Louis Collins, McConnell Brain Imaging Centre, Montreal Neurological Institute,
//   McGill University. Permission to use, copy, modify, and distribute this software and its documentation for
//   any purpose and without fee is hereby granted, provided that the above copyright notice appear in all copies.
//   The authors and McGill University make no representations about the suitability of this software for any
//   purpose. It is provided "as is" without express or implied warranty.
// References: Fonov et al., NeuroImage 54(1), 2011; Fonov et al., NeuroImage 47 (S1), 2009.
// For this demo each volume was cropped to the head, averaged down to 2 mm voxels (93 x 109 x 88), scaled to
// 0-255 and packed into one WebP image: a grid of axial slices, 10 per row, decoded by the browser.
// The values are signal intensity in arbitrary units: unlike CT, MRI has no absolute brightness scale.
const VOLUME = {
    size: [93, 109, 88], // voxels along x (right), y (anterior) and z (superior)
    voxelMm: 2,
    origin: [-91.5, -121.5, -68.5], // MNI coordinates (mm) of the centre of voxel (0, 0, 0)
    tilesPerRow: 10
};

// The three planes. Each view draws one slice: columns along axis u, rows along axis v, cut at the cursor on axis n.
// Radiological convention: the patient's right is on the viewer's left in axial and coronal views
// (so the x axis is flipped), and the face points left in sagittal views.
const PLANES = [
    { key: "axial", title: "Axial", axes: [0, 1, 2], flipX: true, color: "#F5A623", letters: ["R", "L", "A", "P"] },
    { key: "coronal", title: "Coronal", axes: [0, 2, 1], flipX: true, color: "#50C7E0", letters: ["R", "L", "S", "I"] },
    { key: "sagittal", title: "Sagittal", axes: [1, 2, 0], flipX: true, color: "#7ED957", letters: ["A", "P", "S", "I"] }
];
const AXIS_NAMES = ["x", "y", "z"];

// Labelled structures: a point inside each (MNI mm), checked against the template's tissue probability maps.
// A label shows in a view when the slice is within 6 mm of the point. side: which way the text runs from the point.
const STRUCTURES = [
    { name: "Lateral ventricle (CSF)", at: [-6, 10, 14], views: ["axial"], side: "right" },
    { name: "Lateral ventricle (CSF)", at: [15, -21, 22], views: ["coronal"], side: "right" },
    { name: "White matter", at: [-24, 20, 14], views: ["axial"], side: "right" },
    { name: "Cortex (grey matter)", at: [-30, 56, 14], views: ["axial"], side: "left" },
    { name: "Cortex (grey matter)", at: [-14, -20, 43], views: ["coronal"], side: "right" },
    { name: "Thalamus", at: [-10, -20, 10], views: ["axial", "coronal"], side: "right" },
    { name: "Corpus callosum", at: [0, -3, 26], views: ["sagittal"], side: "right" },
    { name: "Pons", at: [0, -28, -28], views: ["sagittal"], side: "left" },
    { name: "Cerebellum", at: [0, -60, -36], views: ["sagittal"], side: "right" },
    { name: "Eye", at: [-31, 56, -45], views: ["axial", "sagittal"], side: "right" }
];

// Unpack a volume from its WebP montage into one byte per voxel, index = x + y * nx + z * nx * ny
async function decodeVolume(base64) {
    const [nx, ny, nz] = VOLUME.size;
    const image = new Image();
    image.src = "data:image/webp;base64," + base64;
    await image.decode();
    const canvas = document.createElement("canvas");
    canvas.width = image.width;
    canvas.height = image.height;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    context.drawImage(image, 0, 0);
    const pixels = context.getImageData(0, 0, image.width, image.height).data;
    const volume = new Uint8Array(nx * ny * nz);
    for (let k = 0; k < nz; k++) {
        const tileX = (k % VOLUME.tilesPerRow) * nx;
        const tileY = Math.floor(k / VOLUME.tilesPerRow) * ny;
        for (let j = 0; j < ny; j++) {
            for (let i = 0; i < nx; i++) {
                volume[i + j * nx + k * nx * ny] = pixels[((tileY + j) * image.width + tileX + i) * 4];
            }
        }
    }
    return volume;
}

// The controls, the three views and the readout each need an element. This splits the page's div into them;
// in your app, they can simply be elements in your HTML.
function createLayout(divElementId) {
    const root = document.getElementById(divElementId);
    root.style.cssText +=
        "display:flex; flex-direction:column; background:#22365B; color:#ffffff;" +
        "font:13px system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;";
    const bar = document.createElement("div");
    bar.style.cssText = "display:flex; flex-wrap:wrap; align-items:center; gap:6px 14px; padding:6px 10px;";
    const range = (id, min, max, value) =>
        `<input type="range" data-id="${id}" min="${min}" max="${max}" value="${value}" style="width:90px; vertical-align:middle">`;
    bar.innerHTML =
        `<span><label><input type="radio" name="${divElementId}-seq" value="t1" checked> T1-weighted</label> ` +
        `<label><input type="radio" name="${divElementId}-seq" value="t2"> T2-weighted</label></span>` +
        `<span>Window ${range("window", 10, 255, 255)} <span data-id="windowValue">255</span></span>` +
        `<span>Level ${range("level", 0, 255, 128)} <span data-id="levelValue">128</span></span>` +
        `<button type="button" data-id="reset">Reset</button>` +
        `<span><label><input type="checkbox" data-id="overlay"> Threshold overlay</label> ` +
        `${range("low", 0, 255, 200)} to ${range("high", 0, 255, 255)} <span data-id="bandValue">200–255</span></span>` +
        `<label><input type="checkbox" data-id="labels" checked> Labels</label>` +
        `<label><input type="checkbox" data-id="ruler" checked> Ruler</label>`;
    const row = document.createElement("div");
    row.style.cssText = "flex:1; min-height:0; display:flex; gap:4px; padding:0 4px;";
    const views = {};
    for (const plane of PLANES) {
        const panel = document.createElement("div");
        panel.style.cssText = "flex:1; min-width:0; display:flex; flex-direction:column;";
        const title = document.createElement("div");
        title.style.cssText = `padding:2px 4px; color:${plane.color}; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;`;
        const chartDiv = document.createElement("div");
        chartDiv.id = `${divElementId}-${plane.key}`;
        chartDiv.style.cssText = "flex:1; min-height:0;";
        const slider = document.createElement("input");
        slider.type = "range";
        slider.setAttribute("aria-label", `${plane.title} slice`);
        slider.style.cssText = `width:100%; margin:4px 0; accent-color:${plane.color};`;
        panel.append(title, chartDiv, slider);
        row.append(panel);
        views[plane.key] = { title, chartDiv, slider };
    }
    const readout = document.createElement("div");
    readout.setAttribute("aria-live", "polite");
    readout.style.cssText = "min-height:2.8em; padding:4px 10px 6px; color:#c8d3e8;";
    root.append(bar, row, readout);
    const inputs = Array.from(bar.getElementsByTagName("input"));
    const input = (id) => inputs.find((element) => element.dataset.id === id);
    const text = (id) => bar.querySelector(`span[data-id="${id}"]`);
    return {
        views,
        readout,
        sequenceInputs: inputs.filter((element) => element.type === "radio"),
        window: input("window"),
        level: input("level"),
        windowValue: text("windowValue"),
        levelValue: text("levelValue"),
        reset: bar.getElementsByTagName("button")[0],
        overlay: input("overlay"),
        low: input("low"),
        high: input("high"),
        bandValue: text("bandValue"),
        labels: input("labels"),
        ruler: input("ruler")
    };
}

async function mriViewer(divElementId) {
    const ui = createLayout(divElementId);

    // #region_A_start
    // A brain MRI viewer: axial, coronal and sagittal slices of one volume as layered heatmaps (the greyscale image,
    // plus a coloured threshold overlay), with linked crosshairs, window/level, labels, a ruler and a voxel readout
    const {
        SciChartSurface,
        NumericAxis,
        NumberRange,
        EAutoRange,
        UniformHeatmapDataSeries,
        UniformHeatmapRenderableSeries,
        HeatmapColorMap,
        HorizontalLineAnnotation,
        VerticalLineAnnotation,
        LineAnnotation,
        TextAnnotation,
        ECoordinateMode,
        EHorizontalAnchorPoint,
        EVerticalAnchorPoint,
        CustomChartModifier2D,
        translateFromCanvasToSeriesViewRect,
        Thickness,
        SciChartJsNavyTheme
    } = SciChart;
    // or, for npm, import { SciChartSurface, ... } from "scichart"

    const volumes = { t1: await decodeVolume(T1_WEBP), t2: await decodeVolume(T2_WEBP) };
    const { size, voxelMm, origin } = VOLUME;
    const stride = [1, size[0], size[0] * size[1]];
    const state = {
        sequence: "t1",
        cursor: [46, 51, 41], // voxel indices: the crosshair position, and the slice each view shows
        window: 255, // width of the intensity range mapped from black to white
        level: 128, // centre of that range
        overlay: false,
        low: 200,
        high: 255
    };
    const mm = (axis, index) => origin[axis] + index * voxelMm;
    const signed = (value) => (value < 0 ? "−" : "+") + Math.abs(value).toFixed(1);

    // Greyscale for the image; a warm colour map for the overlay
    const greyStops = [
        { offset: 0, color: "#000000" },
        { offset: 1, color: "#FFFFFF" }
    ];
    const overlayStops = [
        { offset: 0, color: "#FFD000" },
        { offset: 1, color: "#FF3D00" }
    ];

    const views = [];
    for (const plane of PLANES) {
        const [u, v] = plane.axes;
        const { sciChartSurface, wasmContext } = await SciChartSurface.create(ui.views[plane.key].chartDiv, {
            theme: new SciChartJsNavyTheme(),
            padding: Thickness.fromNumber(0)
        });
        const axisOptions = { isVisible: false, autoRange: EAutoRange.Never, drawMajorGridLines: false, drawMinorGridLines: false };
        const xAxis = new NumericAxis(wasmContext, { ...axisOptions, flippedCoordinates: plane.flipX });
        const yAxis = new NumericAxis(wasmContext, axisOptions);
        sciChartSurface.xAxes.add(xAxis);
        sciChartSurface.yAxes.add(yAxis);

        // Layer 1, the MRI slice. One Float64Array per row of voxels; x and y are in millimetres, each cell one voxel.
        const cells = { xStart: mm(u, -0.5), xStep: voxelMm, yStart: mm(v, -0.5), yStep: voxelMm };
        const imageRows = Array.from({ length: size[v] }, () => new Float64Array(size[u]));
        const imageData = new UniformHeatmapDataSeries(wasmContext, { ...cells, zValues: imageRows });
        const imageColors = new HeatmapColorMap({ minimum: 0, maximum: 255, gradientStops: greyStops });
        const imageSeries = new UniformHeatmapRenderableSeries(wasmContext, {
            dataSeries: imageData,
            colorMap: imageColors,
            fillValuesOutOfRange: true, // below the window is black, above it white
            useLinearTextureFiltering: true // smooth between voxel centres
        });
        // Layer 2, the overlay: voxels inside the threshold band keep their value, the rest are NaN (not drawn)
        const overlayRows = Array.from({ length: size[v] }, () => new Float64Array(size[u]).fill(NaN));
        const overlayData = new UniformHeatmapDataSeries(wasmContext, { ...cells, zValues: overlayRows });
        overlayData.hasNaNs = true;
        const overlayColors = new HeatmapColorMap({ minimum: state.low, maximum: state.high, gradientStops: overlayStops });
        const overlaySeries = new UniformHeatmapRenderableSeries(wasmContext, {
            dataSeries: overlayData,
            colorMap: overlayColors,
            fillValuesOutOfRange: true,
            opacity: 0.55,
            isVisible: false
        });
        sciChartSurface.renderableSeries.add(imageSeries, overlaySeries);

        // Crosshair: where the other two planes cut this one, in their colours
        const others = PLANES.filter((p) => p !== plane);
        const lineFor = (other) => others.find((p) => p.axes[2] === other);
        const vertical = new VerticalLineAnnotation({ x1: 0, stroke: lineFor(u).color, strokeThickness: 1, strokeDashArray: [4, 3] });
        const horizontal = new HorizontalLineAnnotation({ y1: 0, stroke: lineFor(v).color, strokeThickness: 1, strokeDashArray: [4, 3] });
        // Orientation letters at the edges of the view
        const letter = (text, x, y, h, vAnchor) =>
            new TextAnnotation({
                text,
                x1: x,
                y1: y,
                xCoordinateMode: ECoordinateMode.Relative,
                yCoordinateMode: ECoordinateMode.Relative,
                horizontalAnchorPoint: h,
                verticalAnchorPoint: vAnchor,
                fontSize: 14,
                fontWeight: "bold",
                textColor: "#FFFFFFCC"
            });
        sciChartSurface.annotations.add(
            vertical,
            horizontal,
            letter(plane.letters[0], 0.01, 0.5, EHorizontalAnchorPoint.Left, EVerticalAnchorPoint.Center),
            letter(plane.letters[1], 0.99, 0.5, EHorizontalAnchorPoint.Right, EVerticalAnchorPoint.Center),
            letter(plane.letters[2], 0.5, 0.01, EHorizontalAnchorPoint.Center, EVerticalAnchorPoint.Top),
            letter(plane.letters[3], 0.5, 0.92, EHorizontalAnchorPoint.Center, EVerticalAnchorPoint.Bottom)
        );
        // Structure labels: a dot at the point and the name beside it
        const labels = STRUCTURES.filter((s) => s.views.includes(plane.key)).map((s) => {
            const annotation = new TextAnnotation({
                text: s.side === "right" ? `● ${s.name}` : `${s.name} ●`,
                x1: s.at[u],
                y1: s.at[v],
                horizontalAnchorPoint: s.side === "right" ? EHorizontalAnchorPoint.Left : EHorizontalAnchorPoint.Right,
                verticalAnchorPoint: EVerticalAnchorPoint.Center,
                fontSize: 12,
                textColor: "#FFFFFF",
                background: "#00000099"
            });
            sciChartSurface.annotations.add(annotation);
            return { structure: s, annotation };
        });

        const view = { plane, sciChartSurface, xAxis, yAxis, imageRows, imageData, imageSeries, overlayRows, overlayData, overlaySeries, vertical, horizontal, labels };
        views.push(view);
        sciChartSurface.chartModifiers.add(createViewModifier(view));
        // Keep 1 mm the same size across and down, and leave room at the bottom for the watermark
        sciChartSurface.layoutMeasured.subscribe(() => fitView(view));
        const slider = ui.views[plane.key].slider;
        slider.min = "0";
        slider.max = String(size[plane.axes[2]] - 1);
        slider.addEventListener("input", () => {
            const cursor = [...state.cursor];
            cursor[plane.axes[2]] = Number(slider.value);
            moveCursor(cursor);
        });
    }

    // A ruler on the axial view: drag either end to measure a distance in millimetres
    const axial = views[0];
    const ruler = new LineAnnotation({ x1: 45, y1: -76, x2: -45, y2: -76, stroke: "#FF4081", strokeThickness: 2, isEditable: true });
    const rulerText = new TextAnnotation({
        x1: 0,
        y1: -76,
        horizontalAnchorPoint: EHorizontalAnchorPoint.Center,
        verticalAnchorPoint: EVerticalAnchorPoint.Bottom,
        fontSize: 12,
        textColor: "#FF80AB",
        background: "#00000099"
    });
    function updateRuler() {
        rulerText.x1 = (ruler.x1 + ruler.x2) / 2;
        rulerText.y1 = Math.max(ruler.y1, ruler.y2) + 2;
        rulerText.text = `${Math.hypot(ruler.x2 - ruler.x1, ruler.y2 - ruler.y1).toFixed(0)} mm`;
    }
    ruler.dragDelta.subscribe(updateRuler);
    updateRuler();
    axial.sciChartSurface.annotations.add(ruler, rulerText);

    // --- Drawing: the heatmaps are refilled only when the slice, the sequence or the overlay band changes ---
    function fillSlice(view) {
        const [u, v, n] = view.plane.axes;
        const volume = volumes[state.sequence];
        const sliceStart = state.cursor[n] * stride[n];
        for (let b = 0; b < size[v]; b++) {
            const rowStart = sliceStart + b * stride[v];
            const imageRow = view.imageRows[b];
            const overlayRow = view.overlayRows[b];
            for (let a = 0; a < size[u]; a++) {
                const value = volume[rowStart + a * stride[u]];
                imageRow[a] = value;
                if (state.overlay) overlayRow[a] = value >= state.low && value <= state.high && value > 0 ? value : NaN;
            }
        }
        view.imageData.setZValues(view.imageRows);
        if (state.overlay) view.overlayData.setZValues(view.overlayRows);
    }

    function updateCrosshairAndLabels(view) {
        const [u, v, n] = view.plane.axes;
        view.vertical.x1 = mm(u, state.cursor[u]);
        view.horizontal.y1 = mm(v, state.cursor[v]);
        const slicePosition = mm(n, state.cursor[n]);
        for (const { structure, annotation } of view.labels) {
            annotation.isHidden = !ui.labels.checked || Math.abs(structure.at[n] - slicePosition) > 6;
        }
        const { plane } = view;
        ui.views[plane.key].title.textContent =
            `${plane.title} · ${AXIS_NAMES[n]} ${signed(slicePosition)} mm · slice ${state.cursor[n] + 1} of ${size[n]}`;
        ui.views[plane.key].slider.value = String(state.cursor[n]);
    }

    function moveCursor(cursor) {
        const previous = state.cursor;
        state.cursor = cursor;
        for (const view of views) {
            const n = view.plane.axes[2];
            if (cursor[n] !== previous[n]) fillSlice(view);
            updateCrosshairAndLabels(view);
        }
    }

    // Window/level: the colour map spans level ± window / 2, so only the colours change, not the data
    function applyWindowLevel() {
        for (const view of views) {
            view.imageSeries.colorMap.minimum = state.level - state.window / 2;
            view.imageSeries.colorMap.maximum = state.level + state.window / 2;
        }
        ui.windowValue.textContent = String(state.window);
        ui.levelValue.textContent = String(state.level);
    }

    function applyOverlay() {
        ui.bandValue.textContent = `${state.low}–${state.high}`;
        for (const view of views) {
            view.overlaySeries.isVisible = state.overlay;
            view.overlaySeries.colorMap.minimum = state.low;
            view.overlaySeries.colorMap.maximum = Math.max(state.high, state.low + 1);
            if (state.overlay) fillSlice(view);
        }
    }

    // Keep the image undistorted: the same number of millimetres per pixel across and down
    function fitView(view) {
        const rect = view.sciChartSurface.seriesViewRect;
        if (!rect || rect.width < 2 || rect.height < 2) return;
        const [u, v] = view.plane.axes;
        const widthMm = size[u] * voxelMm;
        const heightMm = size[v] * voxelMm;
        const bottomMargin = 0.1; // the share of the height kept clear for the watermark
        const mmPerPixel = Math.max(widthMm / rect.width, heightMm / (rect.height * (1 - bottomMargin)));
        const centreX = mm(u, (size[u] - 1) / 2);
        const centreY = mm(v, (size[v] - 1) / 2);
        const halfWidth = (mmPerPixel * rect.width) / 2;
        const usedHeight = mmPerPixel * rect.height * (1 - bottomMargin);
        const xRange = new NumberRange(centreX - halfWidth, centreX + halfWidth);
        const yRange = new NumberRange(centreY - usedHeight / 2 - mmPerPixel * rect.height * bottomMargin, centreY + usedHeight / 2);
        const differs = (a, b) => Math.abs(a.min - b.min) > 0.01 || Math.abs(a.max - b.max) > 0.01;
        if (differs(view.xAxis.visibleRange, xRange)) view.xAxis.visibleRange = xRange;
        if (differs(view.yAxis.visibleRange, yRange)) view.yAxis.visibleRange = yRange;
    }

    // --- Mouse: click or drag to move the crosshair, scroll to step through slices, hover to read a voxel ---
    function voxelUnderMouse(view, args) {
        const point = translateFromCanvasToSeriesViewRect(args.mousePoint, view.sciChartSurface.seriesViewRect);
        if (!point) return null;
        const [u, v] = view.plane.axes;
        const a = Math.round((view.xAxis.getCurrentCoordinateCalculator().getDataValue(point.x) - origin[u]) / voxelMm);
        const b = Math.round((view.yAxis.getCurrentCoordinateCalculator().getDataValue(point.y) - origin[v]) / voxelMm);
        if (a < 0 || a >= size[u] || b < 0 || b >= size[v]) return null;
        const voxel = [...state.cursor];
        voxel[u] = a;
        voxel[v] = b;
        return voxel;
    }

    function showReadout(view, voxel) {
        if (!voxel) {
            ui.readout.textContent = "Hover over a view to read a voxel. Click or drag to move the crosshair; scroll over a view to change its slice.";
            return;
        }
        const index = voxel[0] * stride[0] + voxel[1] * stride[1] + voxel[2] * stride[2];
        const [x, y, z] = [0, 1, 2].map((axis) => mm(axis, voxel[axis]));
        const side = Math.abs(x) < 1.5 ? "midline" : x > 0 ? "patient's right" : "patient's left";
        ui.readout.textContent =
            `${view.plane.title} view · voxel (${voxel.join(", ")}) · x ${signed(x)}, y ${signed(y)}, z ${signed(z)} mm (${side}) · ` +
            `T1 signal ${volumes.t1[index]}, T2 signal ${volumes.t2[index]} (0–255, arbitrary units)`;
    }

    function createViewModifier(view) {
        let dragging = false;
        class SliceViewModifier extends CustomChartModifier2D {
            modifierMouseDown(args) {
                super.modifierMouseDown(args);
                const voxel = voxelUnderMouse(view, args);
                if (voxel && args.button === 0) {
                    dragging = true;
                    moveCursor(voxel);
                    args.handled = true;
                }
            }
            modifierMouseMove(args) {
                super.modifierMouseMove(args);
                const voxel = voxelUnderMouse(view, args);
                if (dragging && voxel) moveCursor(voxel);
                showReadout(view, voxel);
            }
            modifierMouseUp(args) {
                super.modifierMouseUp(args);
                dragging = false;
            }
            modifierMouseWheel(args) {
                super.modifierMouseWheel(args);
                const n = view.plane.axes[2];
                const cursor = [...state.cursor];
                cursor[n] = Math.min(size[n] - 1, Math.max(0, cursor[n] + (args.mouseWheelDelta > 0 ? -1 : 1)));
                moveCursor(cursor);
                showReadout(view, voxelUnderMouse(view, args));
                args.handled = true;
                if (args.nativeEvent) args.nativeEvent.preventDefault();
            }
            modifierMouseLeave(args) {
                super.modifierMouseLeave(args);
                dragging = false;
                showReadout(view, null);
            }
        }
        return new SliceViewModifier();
    }

    // --- Controls ---
    for (const input of ui.sequenceInputs) {
        input.addEventListener("change", () => {
            state.sequence = input.value;
            views.forEach(fillSlice);
        });
    }
    ui.window.addEventListener("input", () => {
        state.window = Number(ui.window.value);
        applyWindowLevel();
    });
    ui.level.addEventListener("input", () => {
        state.level = Number(ui.level.value);
        applyWindowLevel();
    });
    ui.reset.addEventListener("click", () => {
        state.window = 255;
        state.level = 128;
        ui.window.value = "255";
        ui.level.value = "128";
        applyWindowLevel();
    });
    ui.overlay.addEventListener("change", () => {
        state.overlay = ui.overlay.checked;
        applyOverlay();
    });
    for (const input of [ui.low, ui.high]) {
        input.addEventListener("input", () => {
            state.low = Math.min(Number(ui.low.value), Number(ui.high.value));
            state.high = Math.max(Number(ui.low.value), Number(ui.high.value));
            applyOverlay();
        });
    }
    ui.labels.addEventListener("change", () => views.forEach(updateCrosshairAndLabels));
    ui.ruler.addEventListener("change", () => {
        ruler.isHidden = rulerText.isHidden = !ui.ruler.checked;
    });

    views.forEach(fillSlice);
    views.forEach(updateCrosshairAndLabels);
    applyWindowLevel();
    showReadout(null, null);
    // #region_A_end
}

// The two volumes, each a WebP image of axial slices (see the note at the top of this file)
const T1_WEBP = "";
const T2_WEBP = "";

mriViewer("scichart-root");
